package com.travelbird.trip.repository.querydsl;
import com.querydsl.core.types.dsl.BooleanExpression; import com.querydsl.jpa.impl.JPAQueryFactory; import com.travelbird.trip.entity.*; import jakarta.persistence.EntityManager; import java.util.List; import org.springframework.stereotype.Repository;
@Repository public class TripWishlistQueryRepository {private final JPAQueryFactory query;public TripWishlistQueryRepository(EntityManager em){query=new JPAQueryFactory(em);}public List<TripWishlistPlace> findPage(Long tripId,Long cursor,int limit){QTripWishlistPlace w=QTripWishlistPlace.tripWishlistPlace;BooleanExpression boundary=null;if(cursor!=null){var tuple=query.select(w.addedAt,w.place.id).from(w).where(w.trip.id.eq(tripId),w.place.id.eq(cursor)).fetchOne();if(tuple!=null){var at=tuple.get(w.addedAt);boundary=w.addedAt.lt(at).or(w.addedAt.eq(at).and(w.place.id.lt(cursor)));}}return query.selectFrom(w).join(w.place).fetchJoin().where(w.trip.id.eq(tripId),boundary).orderBy(w.addedAt.desc(),w.place.id.desc()).limit(limit).fetch();}}